const { JSDOM } = require('jsdom');
const fs = require('fs');
const html = fs.readFileSync('/tmp/page.html','utf8');

// Stub fetch BEFORE the page script runs
const POLL = { pipeline:{id:5,ref:'master',status:'failed'},
  jobs:[{name:'build',status:'success'},{name:'unit-test',status:'success'},{name:'integration-test',status:'failed'}],
  trace:'NameError: Optional', changed_files:['app/service.py'],
  scenario:{id:'missing_import',root_cause:'missing import',reasoning_steps:['a','b'],confidence:0.9,risk_score:10,git_diff:'--- a/x\n+++ b/x\n',category:'code'} };
const ANALYZE = { root_cause:'missing import Optional', summary:'add import', confidence:0.9, risk_score:10,
  patch:'--- a/app/service.py\n+++ b/app/service.py\n', reasoning_steps:['step1'], failure_category:'code',
  validation_commands:['pytest'], files_touched:['app/service.py'], manual_triage_minutes:15, auto_triage_minutes:1 };
global.fetch = (url)=>{
  let body;
  if(url.includes('/api/poll')) body=POLL;
  else if(url.includes('/api/analyze')) body=ANALYZE;
  else if(url.includes('/api/metrics')) body={mttr_min:4,auto_fix_rate:87,releases_week:12,risk_score:10,hours_saved_per_week:7.4};
  else if(url.includes('/api/git')) body={branch:'master',commit_hash:'abc',commit_msg:'x',author:'a',commit_time:'t',files_changed:['app/service.py']};
  return Promise.resolve({ json:()=>Promise.resolve(body) });
};

const dom = new JSDOM(html, { runScripts:'dangerously', pretendToBeVisual:true, beforeParse(window){
  window.fetch = global.fetch;
  window.alert = (m)=>console.log('ALERT:',m);
}});
// jsdom runs scripts on load; wait for async fetch chain
setTimeout(()=>{
  const doc = dom.window.document;
  const card = doc.getElementById('ai-card');
  const reason = doc.getElementById('reasoning-cause');
  console.log('ai-card display:', card.style.display);
  console.log('reasoning-cause text:', JSON.stringify(reason.textContent));
  const ok = card.style.display==='block' && reason.textContent.length>0;
  console.log(ok ? 'RESULT: AI CARD SHOWS ✅' : 'RESULT: AI CARD HIDDEN ❌');
}, 500);
